import type {
  MenuItemProps,
  MenuItemLabelProps,
  MenuItemSubtextProps,
  MenuItemHotkeyProps,
  MenuItemLeadingIconProps,
  MenuItemTrailingIconProps,
} from "./menu-item.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { useMenu } from "../../hooks/use-menu";

import { StyledMenuItem, MenuItemClasses } from "./menu-item.styles";

const MenuItemLabel = forwardRef<HTMLSpanElement, MenuItemLabelProps>(
  ({ children, className, ...props }, ref) => (
    <span ref={ref} className={clsx(MenuItemClasses.label, className)} {...props}>
      {children}
    </span>
  ),
);
MenuItemLabel.displayName = "Menu.ItemLabel";

const MenuItemText = ({ children }: { children: React.ReactNode }) => {
  return <div className={MenuItemClasses.text}>{children}</div>;
};
MenuItemText.displayName = "Menu.ItemText";

const MenuItemSubtext = forwardRef<HTMLSpanElement, MenuItemSubtextProps>(
  ({ children, className, ...props }, ref) => (
    <span ref={ref} className={clsx(MenuItemClasses.subtext, className)} {...props}>
      {children}
    </span>
  ),
);
MenuItemSubtext.displayName = "Menu.ItemSubtext";

const MenuItemHotkey = forwardRef<HTMLSpanElement, MenuItemHotkeyProps>(
  ({ children, className, ...props }, ref) => (
    <span ref={ref} className={clsx(MenuItemClasses.hotkey, className)} {...props}>
      {children}
    </span>
  ),
);
MenuItemHotkey.displayName = "Menu.ItemHotkey";

const MenuItemLeadingIcon = forwardRef<HTMLSpanElement, MenuItemLeadingIconProps>(
  ({ children, className, ...props }, ref) => (
    <span ref={ref} className={clsx(MenuItemClasses.leadingIcon, className)} {...props}>
      {children}
    </span>
  ),
);
MenuItemLeadingIcon.displayName = "Menu.ItemLeadingIcon";

const MenuItemTrailingIcon = forwardRef<HTMLSpanElement, MenuItemTrailingIconProps>(
  ({ children, className, ...props }, ref) => (
    <span ref={ref} className={clsx(MenuItemClasses.trailingIcon, className)} {...props}>
      {children}
    </span>
  ),
);
MenuItemTrailingIcon.displayName = "Menu.ItemTrailingIcon";

const MenuItem = forwardRef<HTMLDivElement, MenuItemProps>(
  (
    {
      children,
      className,
      onSelect: propOnSelect,
      variant: variantProp,
      styleSlots,
      style,
      size: sizeProp,
      asChild,
      selected,
      ...props
    },
    ref,
  ) => {
    const { onSelect: contextOnSelect, RadixComponent, variant, size: contextSize } = useMenu();
    const theme = useTheme();
    const size = sizeProp || contextSize;
    const menuItemClasses = clsx(
      MenuItemClasses.root,
      {
        [MenuItemClasses.sm]: size === "sm",
      },
      className,
    );

    const handleSelect = (event: Event | React.SyntheticEvent<HTMLElement, Event>) => {
      const nativeEvent = event as Event;
      propOnSelect?.(nativeEvent);
      contextOnSelect?.(nativeEvent);
    };

    // Automatically wrap string children with MenuItemLabel for convenience
    const content = React.Children.map(children, (child) =>
      typeof child === "string" ? <MenuItemLabel>{child}</MenuItemLabel> : child,
    );

    const hasSubtext = React.Children.toArray(content).some(
      (child) =>
        React.isValidElement(child) &&
        (child.type as { displayName?: string }).displayName === MenuItemSubtext.displayName,
    );

    const contentWithTextWrapper = hasSubtext ? (
      <MenuItemText key="menu-item-text">
        {React.Children.toArray(content).filter(
          (child) =>
            React.isValidElement(child) &&
            (child.type as { displayName?: string }).displayName !==
              MenuItemLeadingIcon.displayName &&
            (child.type as { displayName?: string }).displayName !==
              MenuItemTrailingIcon.displayName &&
            (child.type as { displayName?: string }).displayName !== MenuItemHotkey.displayName,
        )}
      </MenuItemText>
    ) : (
      content
    );

    return (
      <StyledMenuItem
        ref={ref}
        as={RadixComponent.Item}
        asChild={asChild}
        className={menuItemClasses}
        currentTheme={theme}
        data-has-subtext={hasSubtext ? true : undefined}
        data-selected={selected ? "true" : undefined}
        style={style}
        styleSlots={styleSlots}
        variant={variantProp || variant}
        onSelect={handleSelect}
        {...props}
      >
        {asChild
          ? children
          : hasSubtext
            ? [
                React.Children.toArray(content).find(
                  (child) =>
                    React.isValidElement(child) &&
                    (child.type as { displayName?: string }).displayName ===
                      MenuItemLeadingIcon.displayName,
                ),
                contentWithTextWrapper,
                React.Children.toArray(content).find(
                  (child) =>
                    React.isValidElement(child) &&
                    (child.type as { displayName?: string }).displayName ===
                      MenuItemTrailingIcon.displayName,
                ),
                React.Children.toArray(content).find(
                  (child) =>
                    React.isValidElement(child) &&
                    (child.type as { displayName?: string }).displayName ===
                      MenuItemHotkey.displayName,
                ),
              ]
            : content}
      </StyledMenuItem>
    );
  },
);
MenuItem.displayName = "Menu.Item";

export {
  MenuItem,
  MenuItemLabel,
  MenuItemText,
  MenuItemSubtext,
  MenuItemHotkey,
  MenuItemLeadingIcon,
  MenuItemTrailingIcon,
};
